/**
 * Owns Wolf Sorcerer state construction, exact live reads and copied player projection.
 * Inputs are original role/history data; outputs retain existing descriptor, day and pair
 * validation. This boundary never exchanges seats, commits history or closes a frame.
 */
import type {
  WolfSorcererChoice,
  WolfSorcererState,
  WolfSorcererReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const WOLF_SORCERER_ROLE = "wolf_sorcerer" as const;
export const WOLF_SORCERER_POLICY = "awa_wolf_sorcerer_seats_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** Validate without invoking user-owned accessors, iterators or array methods. */
export function getWolfSorcererState(
  role: RoleComponent | undefined,
): WolfSorcererReadState | undefined {
  if (field(role, "role") !== WOLF_SORCERER_ROLE || field(role, "camp") !== Camp.Wolf)
    return undefined;
  const state = field(field(role, "privateState"), "wolfSorcerer");
  if (!exact(state, ["policy", "firstNight", "history"])) return undefined;
  const firstNight = field(state, "firstNight");
  if (field(state, "policy") !== WOLF_SORCERER_POLICY || (firstNight !== 1 && firstNight !== 2))
    return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  let previous = 0;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day < firstNight || day <= previous) return undefined;
    previous = day;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as WolfSorcererReadState;
}
export function createWolfSorcererState(firstNight: 1 | 2): WolfSorcererState {
  return { policy: WOLF_SORCERER_POLICY, firstNight, history: [] };
}
export function projectWolfSorcererState(
  role: RoleComponent | undefined,
): WolfSorcererState | undefined {
  const state = getWolfSorcererState(role);
  if (!state) return undefined;
  const history: WolfSorcererChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: WOLF_SORCERER_POLICY,
    firstNight: field(state, "firstNight") as 1 | 2,
    history,
  };
}

/**
 * 负责 狼术师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_SORCERER_POLICY, createWolfSorcererState, getWolfSorcererState } from "./state";
import {
  wolfSorcererChoicePending,
  wolfSorcererChoiceTargets,
  wolfSorcererPackReady,
} from "./night_frame";
import { WOLF_SORCERER_EXCHANGE_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(WOLF_SORCERER_POLICY).default(WOLF_SORCERER_POLICY),
  firstNight: z.union([z.literal(1), z.literal(2)]).default(2),
});
export const WOLF_SORCERER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WolfSorcerer,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.Villager,
      Role.Psychic,
      Role.Witch,
      Role.Magician,
      Role.Hunter,
      Role.WolfSorcerer,
    ],
    label: roleName("wolf_sorcerer"),
    skillBrief: text("zh-CN", "role.wolf_sorcerer.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    wolfTeam: (role, world) => {
      const known = !!getWolfSorcererState(role)?.history.length;
      const active = known && (!world || wolfSorcererPackReady(world));
      return {
        recognizedByPack: known,
        recognizes: known ? "pack" : "none",
        canChat: active,
        canVoteForKill: active,
      };
    },
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.wolfSorcerer ?? {});
      role.privateState.wolfSorcerer = createWolfSorcererState(value.firstNight);
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, wolfSorcerer: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wolfSorcerer ?? {}),
    },
    toolSpecs: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []),
      {
        name: "swap_night_seats",
        parameters: {
          type: "object",
          properties: {
            first_id: { type: ["integer", "null"], minimum: 1 },
            second_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["first_id", "second_id", "abstain"],
          additionalProperties: false,
        },
        argHint:
          'swap_night_seats args: {"first_id":number|null,"second_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.swap_night_seats.hint",
      },
    ],
    stageDirectives: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "swap_night_seats",
        messageKey: "action.swap_night_seats.directive",
        text: text("zh-CN", "action.swap_night_seats.directive"),
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      swap_night_seats: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getWolfSorcererState(role) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "swap_night_seats" ||
          !wolfSorcererChoicePending(world, actorId, day)
        )
          return { code: RuleError.WolfSorcererUnavailable };
        const { first_id, second_id, abstain } = toolCall.args;
        if (abstain)
          return first_id === null && second_id === null
            ? null
            : { code: RuleError.WolfSorcererTarget };
        const targets = wolfSorcererChoiceTargets(world, day);
        return first_id !== null &&
          second_id !== null &&
          first_id !== second_id &&
          targets.includes(first_id) &&
          targets.includes(second_id)
          ? null
          : { code: RuleError.WolfSorcererTarget };
      },
    },
    nightStages: [WOLF_SORCERER_EXCHANGE_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
    baselineAction: (role, request, pick, pickCamp, locale, world) => {
      if (
        !request.allowedTools.includes("swap_night_seats") ||
        !world ||
        !getWolfSorcererState(role)
      )
        return (
          ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pick,
            pickCamp,
            locale,
            world,
          ) ?? null
        );
      const targets = wolfSorcererChoiceTargets(world, request.context.day);
      return targets.length >= 2
        ? {
            name: "swap_night_seats",
            args: { first_id: targets[0]!, second_id: targets[1]!, abstain: false },
          }
        : { name: "swap_night_seats", args: { first_id: null, second_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("wolf_sorcerer"),
};

/**
 * Owns Wolf Sorcerer native exchange and night target-remapping receipts. Inputs are original
 * participants and the paired choice; outputs are current remaps, pack readiness and close/abort
 * decisions. Only the bound original players share an exchange, without silently replacing its
 * source.
 */
import type { WolfSorcererReadState } from "@ai-werewolf-arena/game-contract";
import { resolveOrderedSeatTarget } from "./seat_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getWolfSorcererState, projectWolfSorcererState, WOLF_SORCERER_ROLE } from "./state";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: WolfSorcererReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function stateIdentity(role: RoleComponent): string {
  const view = projectWolfSorcererState(role);
  if (!view) throw new Error("wolf_sorcerer_original_state_revoked");
  return JSON.stringify(view);
}
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("wolf_sorcerer_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("wolf_sorcerer_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getWolfSorcererState(actor.role) !== b.state || stateIdentity(actor.role) !== b.expectedState)
    throw new Error("wolf_sorcerer_original_state_revoked");
  return b;
}
export function installWolfSorcererBoard(world: World): void {
  if (boards.has(world)) throw new Error("wolf_sorcerer_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: WolfSorcererReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("wolf_sorcerer_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === WOLF_SORCERER_ROLE) {
      if (actorId !== null) throw new Error("wolf_sorcerer_original_roster_invalid");
      actorId = id;
      state = getWolfSorcererState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("wolf_sorcerer_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: stateIdentity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isWolfSorcererBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function beginWolfSorcererNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("wolf_sorcerer_night_invalid");
  const used = new Set<number>();
  for (const choice of projectWolfSorcererState(b.players.get(b.actorId)!.role)!.history)
    if (choice.pair) {
      used.add(choice.pair[0]);
      used.add(choice.pair[1]);
    }
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible =
    day >= b.state.firstNight && b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = { day, closed: false, committed: !eligible, pair: null, targets };
  return eligible ? b.actorId : null;
}
export function wolfSorcererChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitWolfSorcererExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("wolf_sorcerer_choice_scope_invalid");
  let chosen: [number, number] | null = null;
  if (pair !== null) {
    if (types.isProxy(pair) || !Array.isArray(pair))
      throw new Error("wolf_sorcerer_choice_target_invalid");
    const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      pair as object,
    );
    const a = descriptors["0"]?.value,
      z = descriptors["1"]?.value;
    if (
      Reflect.ownKeys(descriptors).length !== 3 ||
      descriptors.length?.value !== 2 ||
      !Number.isSafeInteger(a) ||
      !Number.isSafeInteger(z) ||
      a <= 0 ||
      z <= 0
    )
      throw new Error("wolf_sorcerer_choice_target_invalid");
    if (a === z || !n.targets.get(a)?.life.alive || !n.targets.get(z)?.life.alive)
      throw new Error("wolf_sorcerer_choice_target_invalid");
    chosen = a < z ? [a, z] : [z, a];
  }
  Object.defineProperty(b.state.history, String(b.state.history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
  b.expectedState = stateIdentity(b.players.get(actorId)!.role);
  n.pair = chosen && Object.freeze([chosen[0], chosen[1]] as [number, number]);
  n.committed = true;
}
export interface WolfSorcererResolvedTarget {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function resolveWolfSorcererNightTarget(
  world: World,
  day: number,
  requestedId: number,
  kind: "night_action" | "death_shot" | "original" | "intermediate" = "night_action",
): WolfSorcererResolvedTarget {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("wolf_sorcerer_night_unsettled");
  const original = b.players.get(requestedId);
  if (!original || !original.life.alive) throw new Error("wolf_sorcerer_target_invalid");
  const pair = kind === "original" ? null : n.pair;
  const effectiveId = resolveOrderedSeatTarget(requestedId, null, pair);
  const effective = b.players.get(effectiveId)!;
  if (kind === "night_action" && !effective.life.alive)
    throw new Error("wolf_sorcerer_target_invalid");
  const nightPair = n.pair;
  const requestedVersion = aliveLifeVersion(original.life)!;
  const scope: NightLifeScope = Object.freeze({
    id: effectiveId,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  return Object.freeze({
    requestedId,
    effectiveId,
    scope,
    isCurrent: () => {
      try {
        return (
          requireBoard(world) === b &&
          b.night === n &&
          n.pair === nightPair &&
          !n.closed &&
          originalPlayer(world, original) &&
          originalPlayer(world, effective) &&
          original.life.alive &&
          aliveLifeVersion(original.life) === requestedVersion &&
          aliveLifeVersion(effective.life) === scope.version
        );
      } catch {
        return false;
      }
    },
  });
}
export function closeWolfSorcererNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("wolf_sorcerer_night_unsettled");
  n.closed = true;
}

export function assertWolfSorcererRosterCurrent(world: World): void {
  requireBoard(world);
}
export function wolfSorcererChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}

/** Cleanup only: never validates or repairs a revoked roster, and never records a choice. */
export function abortWolfSorcererNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) n.closed = true;
}

/** Initial pack knowledge is withheld until the first eligible night choice has settled. */
export function wolfSorcererPackReady(world: World): boolean {
  const b = requireBoard(world),
    n = b.night;
  return !!n && n.day >= b.state.firstNight && n.committed;
}

export function wolfSorcererActorId(world: World): number {
  return requireBoard(world).actorId;
}

/**
 * Runs the Wolf Sorcerer exchange opportunity before remapped native actions. Inputs are the
 * current frame and validated paired selection; outputs preserve exchange commitment and its
 * fact. The stage does not own pack readiness or target receipt validity; the frame checks them.
 */
import type { AliveComponent } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getWolfSorcererState } from "./state";
import {
  wolfSorcererActorId,
  assertWolfSorcererRosterCurrent,
  beginWolfSorcererNight,
  commitWolfSorcererExchange,
  wolfSorcererChoiceTargets,
} from "./night_frame";
/** Runs from the configured role set, including after the wolf_sorcerer's death. */
export const WOLF_SORCERER_EXCHANGE_STAGE: NightStageHandler = {
  id: "wolf_sorcerer_exchange",
  priority: 100,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginWolfSorcererNight(ctx.world, day);
    if (actorId === null) {
      const id = wolfSorcererActorId(ctx.world),
        own = ctx.world.getComponent(id, COMPONENT.Role);
      const state = getWolfSorcererState(own)!;
      const reason =
        day < state.firstNight
          ? "not_started"
          : ctx.world.getComponent(id, COMPONENT.Alive)!.alive
            ? "exhausted"
            : "dead";
      ctx.events.push({
        timestamp: Date.now(),
        type: "wolf_sorcerer_exchange_skipped",
        payload: { actorId: id, day, reason },
        audience: Object.freeze([id]),
      });
      return;
    }
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getWolfSorcererState(role)) throw new Error("wolf_sorcerer_actor_invalid");
    const request = ctx.makeRequest(actorId, ["swap_night_seats"], {
      stage: "wolf_sorcerer_exchange",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      sorcerer_candidates: wolfSorcererChoiceTargets(ctx.world, day),
    });
    assertWolfSorcererRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertWolfSorcererRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day)
      throw new Error("wolf_sorcerer_exchange_stale");
    if (action?.name !== "swap_night_seats")
      throw new Error("wolf_sorcerer_exchange_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertWolfSorcererRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day)
      throw new Error("wolf_sorcerer_exchange_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "swap_night_seats")
      throw new Error("wolf_sorcerer_exchange_action_invalid");
    const args = validated.sanitizedCall.args;
    const pair: [number, number] | null = args.abstain ? null : [args.first_id!, args.second_id!];
    commitWolfSorcererExchange(ctx.world, actorId, day, pair);
    ctx.events.push({
      timestamp: Date.now(),
      type: "wolf_sorcerer_exchange_committed",
      payload: {
        actorId,
        day,
        pair: pair && [Math.min(pair[0], pair[1]), Math.max(pair[0], pair[1])],
      },
      audience: Object.freeze([actorId]),
    });
  },
};

